import type { ReactNode, Ref } from 'react'
import { Accordion as BaseAccordion } from '@base-ui/react/accordion'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Accordion.module.css'

export interface AccordionItem {
  value: string
  title: ReactNode
  content: ReactNode
  disabled?: boolean
}

export interface AccordionProps {
  ref?: Ref<HTMLDivElement>
  items: AccordionItem[]
  /** Controlled: the values of the open items. */
  value?: string[]
  defaultValue?: string[]
  /** Base UI's event details are dropped. */
  onValueChange?: (value: string[]) => void
  /** Allow more than one item open at once. */
  multiple?: boolean
  appearance?: 'outlined' | 'flush'
  size?: 'sm' | 'md'
  /** The heading element each trigger sits in. Match it to the page's outline. */
  headingLevel?: 2 | 3 | 4 | 5 | 6
  disabled?: boolean
  className?: string
}

export function Accordion({
  items,
  onValueChange,
  appearance = 'outlined',
  size = 'md',
  headingLevel = 3,
  className,
  ...props
}: AccordionProps) {
  const Heading = `h${headingLevel}` as const
  return (
    <BaseAccordion.Root
      {...props}
      onValueChange={onValueChange && ((next) => onValueChange(next as string[]))}
      // Collapsed panels stay in the DOM as hidden="until-found", so the
      // browser's find-in-page can reach text inside them and open them.
      hiddenUntilFound
      className={cn(styles.accordion, styles[appearance], styles[size], className)}
    >
      {items.map((item) => (
        <BaseAccordion.Item key={item.value} value={item.value} disabled={item.disabled} className={styles.item}>
          <BaseAccordion.Header render={<Heading />} className={styles.header}>
            <BaseAccordion.Trigger className={styles.trigger}>
              <span className={styles.title}>{item.title}</span>
              <Icon name="chevron-down" className={styles.chevron} />
            </BaseAccordion.Trigger>
          </BaseAccordion.Header>
          <BaseAccordion.Panel className={styles.panel}>
            <div className={styles.content}>{item.content}</div>
          </BaseAccordion.Panel>
        </BaseAccordion.Item>
      ))}
    </BaseAccordion.Root>
  )
}

.accordion {
  --accordion-pad-inline: var(--space-4);
  --accordion-pad-block: var(--space-3);
  display: flex;
  flex-direction: column;
  font-family: var(--font-sans);
  color: var(--foreground);
}

.sm {
  --accordion-pad-inline: var(--space-3);
  --accordion-pad-block: var(--space-2);
}

/* Items are separated by --border lines (non-interactive, so the lighter
   border); outlined also frames the whole set. */
.item + .item {
  border-block-start: 1px solid var(--border);
}

.outlined {
  border: 1px solid var(--border);
  border-radius: var(--radius-panel);
  overflow: hidden;
}

.flush .item:last-child {
  border-block-end: 1px solid var(--border);
}

.flush {
  --accordion-pad-inline: 0;
}

.header {
  margin: 0;
  font: inherit;
}

.trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  inline-size: 100%;
  margin: 0;
  padding: var(--accordion-pad-block) var(--accordion-pad-inline);
  border: 0;
  background: transparent;
  color: inherit;
  font-family: inherit;
  font-size: var(--text-body);
  line-height: var(--leading-body);
  font-weight: 500;
  text-align: start;
  cursor: var(--cursor-button);
}

.sm .trigger {
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
}

.trigger:hover {
  background: var(--accent);
}

/* Inset in the outlined container, whose clipping would cut an outside
   ring off. Flush has no clipping and no side padding, so an inset ring
   would touch the title; it goes outside instead. */
.trigger:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}
.flush .trigger:focus-visible {
  outline-offset: 2px;
}

.trigger[data-disabled] {
  cursor: var(--cursor-disabled);
  opacity: 0.5;
}

.trigger[data-disabled]:hover {
  background: transparent;
}

.title {
  min-inline-size: 0;
}

.chevron {
  flex-shrink: 0;
  font-size: var(--space-4);
  color: var(--muted-foreground);
  transition: rotate 150ms;
}

.trigger[data-panel-open] .chevron {
  rotate: 180deg;
}

/* Base UI measures the content into --accordion-panel-height; animating
   height to it and to 0 at the start and end states is its documented
   pattern. */
.panel {
  block-size: var(--accordion-panel-height);
  overflow: hidden;
  transition: block-size 150ms ease-out;
}

.panel[data-starting-style],
.panel[data-ending-style] {
  block-size: 0;
}

.content {
  padding: 0 var(--accordion-pad-inline) var(--accordion-pad-block);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  color: var(--muted-foreground);
}

.sm .content {
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
}

@media (prefers-reduced-motion: reduce) {
  .panel,
  .chevron {
    transition: none;
  }
}

/* md triggers are 44px already. sm is 32px, and triggers are stacked edge to
   edge, so an invisible 44px hit area would overlap the next trigger's and
   a tap could open the wrong item. On touch, sm grows to 44px instead. */
@media (pointer: coarse) {
  .trigger {
    min-block-size: 44px;
  }
}
